mapper.insert:
INSERT INTO ${tableName} ( warning_order_id,warning_source,report_type,task_id,warning_type_id, alarm_time,tenant_id,tenant_name,province_name,province_code, city_name,city_code,county_code,county_name,longitude, latitude,alarm_body,channel_code,channel_name,device_code, device_name,ptz_p,ptz_t,ptz_z,remark, description,address,alarm_code,voice,link_id, link_name,flow_node_time,process_id,process_name,group_id, creator,time_limit,algorithm_code,emergency_level,order_status, flow_template,find_name,find_mobile,grid_id,grid_name, video_url,file_img_url_src,file_img_url_icon,modifier_date,create_time, delete_flag,importance_level,judge_result,judge_type,flow_id,role_id,industry_code,app_ver_code, alarm_param,alarm_param_value, extra_field, sub_scenes, hori_azimuth_angle,confidence_level,confidence_level_min,confidence_level_max,comp_confidence_level,msg_type, msg_id,notice_resource,front_alarm_pic_url,front_alarm_vedio_url,preset_id,camera_alarm_type,is_second_judge,second_judge_result,town_code,town_name,feature_pan, feature_tilt,real_link_type,enlarge_flag,before_dispatch_flag,enable_acceptance_mode,time_limit_acceptance,device_pitch,device_horizontal,alarm_reason,is_second_identify, second_identify_result,linkage_algorithm,transparent_fields,pitch_angle,hori_field_angle,vertical_field_angle,device_address,flight_route_id,task_record_id ) VALUES
(#{item.warningOrderId}, #{item.warningSource}, #{item.reportType}, #{item.taskId},#{item.alarmType}, #{item.alarmTime},#{item.tenantId},#{item.tenantName},#{item.provinceName},#{item.provinceCode}, #{item.cityName},#{item.cityCode},#{item.countyCode},#{item.countyName},#{item.longitude}, #{item.latitude},#{item.alarmBody},#{item.channelCode},#{item.channelName},#{item.deviceCode}, #{item.deviceName},#{item.pan},#{item.tilt},#{item.zoom},#{item.remark}, #{item.description},#{item.address},#{item.alarmCode},#{item.voice},#{item.linkId}, #{item.linkName},#{item.flowNodeTime},#{item.processId},#{item.processName},#{item.groupId}, #{item.createUser},#{item.timeLimit},#{item.algorithmCode},#{item.emergencyLevel},#{item.orderStatus}, #{item.flowTemplate},#{item.findName},#{item.findMobile},#{item.gridId},#{item.gridName}, #{item.alarmVideoUrl},#{item.originalPictureUrl},#{item.alarmPictureUrl},now(),now(), '0',#{item.importanceLevel},#{item.judgeResult},#{item.judgeType},#{item.flowId},#{item.roleId},#{item.industryCode},#{item.appVerCode}, #{item.alarmParam},#{item.alarmParamValue},#{item.extraField},#{item.subScenes},#{item.horiAzimuthAngle},#{item.confidenceLevel},#{item.confidenceLevelMin},#{item.confidenceLevelMax},#{item.compConfidenceLevel},#{item.msgType}
,#{item.extraInfo.msgId},#{item.extraInfo.noticeResource},#{item.extraInfo.frontAlarmPicUrl},#{item.extraInfo.frontAlarmVedioUrl},#{item.extraInfo.presetId}
,null,null,null,null,null
,#{item.cameraAlarmType},#{item.isSecondJudge},#{item.secondJudgeResult},#{item.townCode},#{item.townName},#{item.featurePan},#{item.featureTilt},#{item.realLinkType},#{item.enlargeFlag},#{item.beforeDispatchFlag},#{item.enableAcceptanceMode}, #{item.timeLimitAcceptance},#{item.devicePitch},#{item.deviceHorizontal},#{item.alarmReason},#{item.isSecondIdentify},#{item.secondIdentifyResult},#{item.linkageAlgorithm},#{item.transparentFields},#{item.pitchAngle},#{item.horiFieldAngle}, #{item.verticalFieldAngle},#{item.deviceAddress},#{item.flightRouteId},#{item.taskRecordId} )

mapper.select:
SELECT agent_extend_field
FROM ${tableName}
WHERE warning_order_id = #{warningOrderId}
LIMIT 1

mapper.update:
UPDATE ${tableName}
SET scene_template = #{sceneTemplate},
    ai_judge_status = #{aiJudgeStatus},
    modifier_date = NOW()
WHERE warning_order_id = #{warningOrderId}

UPDATE ${tableName}
