mapper.select:
select USER_ID,tenant_id from sys_user where is_tenant_admin = '1' and DEL_FLAG = '0' and STATUS = '0'

    AND tenant_id in

        #{item}

SELECT a.alarm_body AS alarmBody, a.warning_order_id AS orderId, a.warning_type_id AS warningTypeId, IF(a.alarm_time IS NULL,'',DATE_FORMAT(a.alarm_time,'%Y-%m-%d %H:%i:%s')) as alarmTime, IF(a.create_time IS NULL,'',DATE_FORMAT(a.create_time,'%Y-%m-%d %H:%i:%s')) as createTime, a.province_code AS provinceId, a.city_code AS cityId, a.county_code AS countyId, a.address, a.longitude, a.latitude, a.emergency_level AS emergencyLevel, a.tenant_id AS tenantId, a.device_code AS deviceCode, a.device_name AS deviceName, a.channel_code AS channelCode, a.channel_name AS channelName, a.alarm_code AS alarmCode, a.order_status AS orderStatus, a.warning_source AS warningSource, a.org_record AS orgRecord, a.user_record AS userRecord, a.flow_template AS flowTemplate, a.flow_id AS flowId, a.link_name AS linkName, a.process_id AS processId, a.process_name AS processName, a.time_limit AS timeLimit, a.app_ver_code as tradeVerCode, a.industry_code as industryCode, a.link_id as linkId, a.real_link_type as realLinkType, a.judge_result as judgeResult, a.grid_id as gridId from ${tableName} a where 1 = 1
and a.warning_order_id = #{orderId}
AND a.tenant_id = #{tenantId}
AND a.order_status = #{orderStatus}
AND a.delete_flag = #{deleteFlag}
AND a.link_id = #{linkId}
AND a.enable_acceptance_mode = #{enableAcceptanceMode}

SELECT t.tenant_id, t.industry_code, t.app_ver_code, t.vehicle_number, t.black_or_white, t.vehicle_type, t.valid_period FROM vm_checkpoint_vehicle_license_plate_t t WHERE t.delete_flag = 0 AND t.vehicle_number = #{vehicleNumber}
AND t.tenant_id in
#{tenantId}
AND t.industry_code in
#{industryCode}

SELECT IFNULL(pt.vehicle_number,'') AS vehicleNumber, IFNULL(pt.app_ver_code,'') AS appVerCode, IFNULL(pt.valid_period,'') AS validPeriod, IFNULL(pt.black_or_white,'') AS blackOrWhite FROM vm_algorithm_give_config ac LEFT JOIN vm_algorithm_give_license_rel_t t ON t.config_id = ac.id LEFT JOIN vm_checkpoint_vehicle_license_plate_t pt ON pt.vehicle_number = t.vehicle_number AND pt.black_or_white = t.black_or_white AND pt.delete_flag = 0 WHERE ac.`status` = '0' AND ac.delete_flag = 0 AND ac.device_code = #{deviceCode} AND ac.alarm_type = #{alarmType}
AND ac.tenant_id in
#{tenantId}
AND ac.industry_code in
#{industryCode}
